(()=>{'use strict';const $=id=>document.getElementById(id),key='revista-negocios-demo-v1',esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const labels={received:'Solicitud recibida',pending:'En revisión',prepared:'Ficha preparada',preview:'Vista previa',approved:'Aprobada en demo',published:'Publicada en demo',paused:'Pausada',archived:'Dada de baja'};const seed=()=>[{id:'todolisto',name:'TodoListo.uy',category:'Hogar y herramientas',area:'',description:'Distribuidora de herramientas y artículos de cocina. Consultá productos y disponibilidad.',services:'Herramientas\nArtículos de cocina',phone:'091685800',website:'https://todolisto.uy/',instagram:'https://www.instagram.com/todolisto.uydistribuidora/',address:'',hours:'',delivery:'Montevideo: envío $150. Interior: por agencias. Confirmar condiciones y disponibilidad.',promo:'15% de descuento en herramientas al mencionar Revista Montevideo. Condiciones y vigencia pendientes de confirmar.',logo:'assets/todolisto-logo-marcas-png-web.webp',banner:'',photos:['assets/rociador-todolisto.jpg'],status:'pending'}];let db=seed(),selected='todolisto',page=1,view='admin',editPhotos=[],requestPhotos=[],media={edit:{logo:'',banner:''},request:{logo:'',banner:''}};try{const x=JSON.parse(localStorage.getItem(key));if(Array.isArray(x)&&x.length&&x.every(b=>b&&typeof b.id==='string'&&typeof b.name==='string'&&labels[b.status]&&Array.isArray(b.photos)))db=x}catch{}for(const b of db){if(!b.logo&&b.id==='todolisto'&&b.photos[0]==='assets/todolisto-logo-marcas-png-web.webp'){b.logo=b.photos.shift()}b.banner=b.banner||''}selected=db[0].id;
const definitions=[['name','Nombre del negocio *','text',true],['category','Rubro *','text',true],['area','Barrio','text'],['phone','WhatsApp público *','tel',true],['description','Presentación del negocio *','textarea',true],['services','Productos o servicios destacados (uno por línea)','textarea'],['website','Página web','url'],['instagram','Instagram (enlace completo)','url'],['address','Dirección para publicar, si corresponde','text'],['hours','Horarios de atención','text'],['delivery','Entregas y zona de atención','textarea'],['promo','Promoción y sus condiciones, si corresponde','textarea'],['type','Tipo de módulos: commerce / realEstate / service / other','text'],['subcategory','Subcategoría','text'],['brand','Marca / oficina','text'],['email','Email','email'],['about','Presentación personal / profesional','textarea'],['video','Video MP4 o WebM (URL)','url'],['story','Historia del negocio','textarea'],['startYear','Año de comienzo','text'],['founders','Fundadores','text'],['anecdotes','Anécdotas y trayectoria','textarea'],['modulesJson','Módulos: propiedades / productos / trabajos (JSON)','textarea'],['adviceJson','Consejos para revisión editorial (JSON)','textarea'],['historyPhotosJson','Fotografías antiguas (JSON de URLs)','textarea']];function buildForm(id,prefix){$(id).innerHTML='<div class="fields">'+definitions.map(([k,l,t,req])=>`<label class="${t==='textarea'?'wide':''}">${l}${t==='textarea'?`<textarea name="${k}" maxlength="${k.endsWith('Json')?60000:3000}" ${req?'required':''}></textarea>`:`<input name="${k}" type="${t}" maxlength="${t==='url'?400:180}" ${req?'required':''}>`}</label>`).join('')+`<div class="wide media-specs"><h3>Imágenes del negocio</h3><p>Si ya tenés las piezas diseñadas, envialas con estas medidas. Si no tenés banner, mandanos las fotos y lo armamos.</p><label>Logo · 800 × 800 px<input id="${prefix}-logo" type="file" accept="image/jpeg,image/png,image/webp"><span class="help">Cuadrado. PNG con fondo transparente recomendado. Logo completo y sin recortar.</span></label><div id="${prefix}-logo-preview" class="media-preview"></div><label>Banner principal · 1920 × 640 px<input id="${prefix}-banner" type="file" accept="image/jpeg,image/png,image/webp"><span class="help">Horizontal, proporción 3:1. Dejales 80 px de margen a textos y logos para que se vean completos.</span></label><div id="${prefix}-banner-preview" class="media-preview"></div><label>Galería · hasta 10 fotos<input id="${prefix}-photos" type="file" accept="image/jpeg,image/png,image/webp" multiple><span class="help">Productos, trabajos o local. Recomendado: al menos 1200 px en el lado más largo. Hasta 2 MB por archivo, en JPG, PNG o WebP. El logo y el banner no cuentan dentro de las 10 fotos.</span></label><div id="${prefix}-photo-list" class="photo-list"></div><p class="help">En esta demo se guardan copias livianas en el navegador. Conservá los originales para la publicación definitiva.</p></div></div>`;$(id).onsubmit=e=>e.preventDefault();$(prefix+'-photos').onchange=e=>addPhotos(prefix,e.target);for(const kind of ['logo','banner'])$(prefix+'-'+kind).onchange=e=>addMedia(prefix,kind,e.target)}
function note(t,error=false){$('feedback').textContent=t;$('feedback').style.color=error?'#a12626':'#086c64'}function persist(next){try{localStorage.setItem(key,JSON.stringify(next));db=next;return true}catch{note('No se pudo guardar en este navegador. Tus datos siguen en el formulario. Probá con fotos más livianas o descargá el respaldo.',true);return false}}
function photosRender(prefix){const photos=prefix==='edit'?editPhotos:requestPhotos;$(prefix+'-photo-list').innerHTML=photos.map((p,i)=>`<div class="photo-item"><img src="${esc(p)}" alt="Imagen ${i+1}"><button type="button" data-remove="${i}">Quitar ${i+1}</button></div>`).join('');$(prefix+'-photo-list').querySelectorAll('button').forEach(b=>b.onclick=()=>{photos.splice(Number(b.dataset.remove),1);photosRender(prefix)})}async function addPhotos(prefix,input){const target=prefix==='edit'?editPhotos:requestPhotos,files=[...input.files];if(target.length+files.length>10||files.some(f=>!['image/jpeg','image/png','image/webp'].includes(f.type)||f.size>2*1024*1024)){note('Elegí como máximo 10 fotos en JPG, PNG o WebP, de hasta 2 MB cada una.',true);input.value='';return}try{const added=await Promise.all(files.map(lightImage));target.push(...added);photosRender(prefix);note('Fotos listas. Guardá los cambios para conservarlas.')}catch{note('No pudimos leer una de las fotos. Volvé a seleccionarla.',true)}input.value=''}
function lightImage(file){return new Promise((resolve,reject)=>{const url=URL.createObjectURL(file),img=new Image();img.onerror=()=>{URL.revokeObjectURL(url);reject()};img.onload=()=>{try{const ratio=Math.min(1,1200/Math.max(img.width,img.height)),canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(img.width*ratio));canvas.height=Math.max(1,Math.round(img.height*ratio));canvas.getContext('2d').drawImage(img,0,0,canvas.width,canvas.height);let quality=.85,data=canvas.toDataURL('image/webp',quality);while(data.length>240000&&quality>.25){quality-=.1;data=canvas.toDataURL('image/webp',quality)}if(data.length>300000)throw Error();resolve(data)}catch{reject()}finally{URL.revokeObjectURL(url)}};img.src=url})}function renderMedia(prefix){for(const kind of ['logo','banner']){const box=$(prefix+'-'+kind+'-preview'),src=media[prefix][kind];box.innerHTML=src?`<img src="${esc(src)}" alt="${kind==='logo'?'Logo':'Banner'} del negocio"><button type="button">Quitar ${kind}</button>`:'';const button=box.querySelector('button');if(button)button.onclick=()=>{media[prefix][kind]='';renderMedia(prefix)}}}async function addMedia(prefix,kind,input){const f=input.files[0];if(!f)return;if(!['image/jpeg','image/png','image/webp'].includes(f.type)||f.size>2*1024*1024){note('El archivo debe ser JPG, PNG o WebP, de hasta 2 MB.',true);input.value='';return}try{media[prefix][kind]=await lightImage(f);renderMedia(prefix);note('Imagen lista. Guardá los cambios para conservarla.')}catch{note('No pudimos preparar la imagen. Probá con un archivo más liviano.',true)}input.value=''}
function current(){return db.find(b=>b.id===selected)}function loadEditor(){const b=current();if(!b)return;for(const [k]of definitions)$('edit-form').elements.namedItem(k).value=k==='modulesJson'?JSON.stringify(b.modules||{},null,2):k==='adviceJson'?JSON.stringify(b.advice||[],null,2):k==='historyPhotosJson'?JSON.stringify(b.historyPhotos||[],null,2):b[k]||'';editPhotos=[...b.photos];media.edit={logo:b.logo||'',banner:b.banner||''};renderMedia('edit');photosRender('edit');$('state').textContent=labels[b.status];$('pause').disabled=!['approved','published'].includes(b.status);$('archive').disabled=b.status==='archived';$('approve').disabled=['approved','published'].includes(b.status);renderRecords()}
function renderRecords(){const box=$('records');box.innerHTML=db.map(b=>`<button class="record ${selected===b.id?'selected':''}" data-id="${esc(b.id)}"><strong>${esc(b.name||'Nuevo negocio')}</strong><span>${esc(labels[b.status])}</span></button>`).join('');box.querySelectorAll('button').forEach(b=>b.onclick=()=>{selected=b.dataset.id;loadEditor();note('Ficha seleccionada. Guardá los cambios antes de cambiar de negocio.')});$('count-all').textContent=db.length;$('count-pending').textContent=db.filter(b=>b.status==='pending').length;$('count-approved').textContent=db.filter(b=>['approved','published'].includes(b.status)).length}
function readForm(id,photos){const form=$(id);if(!form.reportValidity())return null;const o={};for(const [k]of definitions)o[k]=form.elements.namedItem(k).value.trim();if(!o.name||!o.category||!o.description){note('Completá nombre, rubro y presentación.',true);return null}if(!/^\+?[\d\s()-]{8,20}$/.test(o.phone)){note('Revisá el WhatsApp: escribí el número completo con su código de país si corresponde.',true);form.elements.phone.focus();return null}for(const k of ['website','instagram'])if(o[k]&&!/^https?:\/\//i.test(o[k])){note('Los enlaces deben comenzar con https:// o http://.',true);return null}try{o.modules=JSON.parse(o.modulesJson||'{}');o.advice=JSON.parse(o.adviceJson||'[]');o.historyPhotos=JSON.parse(o.historyPhotosJson||'[]');if(!o.modules||typeof o.modules!=='object'||Array.isArray(o.modules)||!Array.isArray(o.advice)||!Array.isArray(o.historyPhotos))throw Error();delete o.modulesJson;delete o.adviceJson;delete o.historyPhotosJson}catch{note('Revisá el JSON de módulos, consejos y fotos antiguas.',true);return null}o.photos=[...photos];Object.assign(o,media[id==='edit-form'?'edit':'request']);return o}
function update(data,message){const next=db.map(b=>b.id===selected?{...b,...data}:b);if(!persist(next))return false;loadEditor();renderSearch();note(message);return true}function showView(v){view=v;document.querySelectorAll('.view').forEach(e=>e.hidden=e.id!==v);document.querySelectorAll('[data-view]').forEach(b=>{if(b.dataset.view===v)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current')});note('');if(v==='search'){page=1;refreshFilters();renderSearch()}}
function refreshFilters(){const approved=db.filter(b=>['approved','published'].includes(b.status));for(const [id,k,title]of [['filter-category','category','Todos los rubros'],['filter-area','area','Todos los barrios']]){const prev=$(id).value;$(id).innerHTML=`<option value="">${title}</option>`+[...new Set(approved.map(b=>b[k]).filter(Boolean))].sort().map(v=>`<option value="${esc(v)}">${esc(v)}</option>`).join('');$(id).value=[...$(id).options].some(o=>o.value===prev)?prev:''}}
const normalize=s=>String(s||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();function renderSearch(){const q=normalize($('query').value),cat=$('filter-category').value,area=$('filter-area').value;const rows=db.filter(b=>['approved','published'].includes(b.status)&&(!cat||b.category===cat)&&(!area||b.area===area)&&normalize([b.name,b.description,b.services].join(' ')).includes(q));const pages=Math.max(1,Math.ceil(rows.length/6));page=Math.min(page,pages);$('results-count').textContent=rows.length+' negocio(s) aprobado(s) en esta prueba.';$('results').innerHTML=rows.length?rows.slice((page-1)*6,page*6).map(b=>`<article class="result">${b.photos[0]?`<img src="${esc(b.photos[0])}" alt="${esc(b.name)}">`:''}<div class="result-body"><small>${esc(b.category)}</small><h3>${esc(b.name)}</h3><p>${esc(b.area||'Barrio pendiente de completar')}</p><p>${esc(b.description.slice(0,140))}</p><button data-profile="${esc(b.id)}">Ver ficha</button></div></article>`).join(''):'<div class="empty"><h3>No hay resultados todavía.</h3><p>Aprobá TodoListo desde el panel o probá otros filtros. Solo aparecen fichas aprobadas.</p></div>';$('results').querySelectorAll('[data-profile]').forEach(b=>b.onclick=()=>openProfile(db.find(x=>x.id===b.dataset.profile)));$('page-label').textContent='Página '+page+' de '+pages;$('prev').disabled=page<=1;$('next').disabled=page>=pages}
function openProfile(b){const digits=b.phone.replace(/\D/g,''),wa=digits.startsWith('0')?'598'+digits.slice(1):digits;const links=[`<a href="https://wa.me/${wa}?text=Hola%2C%20vi%20tu%20negocio%20en%20Revista%20Montevideo" target="_blank" rel="noopener">Consultar por WhatsApp</a>`];for(const [k,l]of [['website','Visitar web'],['instagram','Instagram']])if(/^https?:\/\//i.test(b[k]))links.push(`<a href="${esc(b[k])}" target="_blank" rel="noopener">${l}</a>`);$('profile-content').innerHTML=`<p class="profile-notice">VISTA PREVIA · Ficha de demostración. No publicada en el directorio real.</p>${b.banner?`<img class="profile-banner" src="${esc(b.banner)}" alt="${esc(b.name)}">`:''}${b.logo?`<img class="profile-logo" src="${esc(b.logo)}" alt="Logo de ${esc(b.name)}">`:""}<small>${esc(b.category)}</small><h1>${esc(b.name)}</h1><p class="profile-desc">${esc(b.description)}</p><p><b>${esc(b.phone)}</b></p><div class="profile-links">${links.join('')}</div><div class="profile-meta">${[['Barrio',b.area],['Dirección',b.address],['Horarios',b.hours],['Entregas',b.delivery]].map(([l,v])=>`<div><b>${l}</b>${esc(v||'Consultar al negocio')}</div>`).join('')}</div><h2>Productos y servicios</h2><ul>${b.services.split('\n').filter(Boolean).map(s=>`<li>${esc(s)}</li>`).join('')}</ul>${b.promo?`<div class="profile-promo"><b>Beneficio informado</b><p>${esc(b.promo)}</p></div>`:''}<div class="profile-gallery">${b.photos.map(p=>`<img src="${esc(p)}" alt="Producto o servicio de ${esc(b.name)}">`).join('')}</div>`;const data=b.modules||{};let more='';for(const [key,title]of [['properties','Propiedades destacadas'],['products','Productos destacados'],['works','Trabajos realizados']])if(Array.isArray(data[key]))more+='<h2>'+title+'</h2>'+data[key].slice(0,3).map(p=>'<article><h3>'+esc(p.title)+'</h3><p>'+esc(p.area||'')+' '+esc(p.price||'')+'</p><p>'+esc(p.description||'')+'</p></article>').join('');if(b.about)more='<h2>Conocé el negocio</h2><p>'+esc(b.about)+'</p>'+more;if(b.video&&/^https?:\/\//.test(b.video))more+='<h2>Conocé mi forma de trabajar</h2><video controls playsinline preload="metadata" style="width:100%" src="'+esc(b.video)+'"></video>';if(b.story)more+='<h2>La historia detrás del negocio</h2><p>'+esc(b.story)+'</p>';if(Array.isArray(b.advice))more+='<h2>Consejos profesionales</h2>'+b.advice.map(a=>'<h3>'+esc(a.title)+'</h3><p>'+esc(a.text)+'</p>').join('');$('profile-content').insertAdjacentHTML('beforeend',more);$('profile').showModal()}
buildForm('edit-form','edit');buildForm('request-form','request');document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>showView(b.dataset.view));$('save').onclick=()=>{const data=readForm('edit-form',editPhotos);if(data)update({...data,status:'pending'},'Cambios guardados. La ficha quedó pendiente de revisión.')};$('preview').onclick=()=>{const data=readForm('edit-form',editPhotos);if(data){update({...data,status:'preview'},'Vista previa preparada en este navegador.');openProfile({...current(),...data})}};$('approve').onclick=()=>{const data=readForm('edit-form',editPhotos);if(data)update({...data,status:'approved'},'Ficha aprobada en demo. Ya aparece en el buscador de prueba.')};$('pause').onclick=()=>update({status:'paused'},'Ficha pausada. Ya no aparece en el buscador de prueba.');$('archive').onclick=()=>update({status:'archived'},'Negocio dado de baja en la demo. Sus datos se conservan y podés volver a aprobarlo.');$('new').onclick=()=>{const id=crypto.randomUUID();if(persist([...db,{id,name:'Nuevo negocio',category:'',description:'',services:'',phone:'',website:'',instagram:'',area:'',address:'',hours:'',delivery:'',promo:'',photos:[],status:'pending'}])){selected=id;loadEditor();note('Completá la nueva ficha por escrito.')}};$('submit-request').onclick=()=>{const data=readForm('request-form',requestPhotos);if(!data)return;if(!$('consent').checked){note('Falta confirmar la autorización del formulario.',true);$('consent').focus();return}const id=crypto.randomUUID();if(persist([...db,{...data,id,status:'pending'}])){$('request-form').reset();$('consent').checked=false;requestPhotos=[];media.request={logo:'',banner:''};renderMedia('request');photosRender('request');selected=id;loadEditor();showView('admin');note('Solicitud de prueba recibida. Está pendiente de revisión y todavía no aparece en el buscador.')}};for(const id of ['query','filter-category','filter-area'])$(id).addEventListener('input',()=>{page=1;renderSearch()});$('prev').onclick=()=>{page--;renderSearch()};$('next').onclick=()=>{page++;renderSearch()};$('profile').querySelector('.close').onclick=()=>$('profile').close();$('reset').onclick=()=>$('confirm').showModal();$('cancel-reset').onclick=()=>$('confirm').close();$('confirm-reset').onclick=()=>{if(persist(seed())){selected='todolisto';loadEditor();refreshFilters();renderSearch();$('confirm').close();note('Demo restablecida con TodoListo pendiente de revisión.')}};$('export').onclick=()=>{const blob=new Blob([JSON.stringify({type:'demo-no-publicada',businesses:db},null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='revista-negocios-prueba.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);note('Se descargaron los datos de prueba.')};$('prepare').onclick=()=>{const data=readForm('edit-form',editPhotos);if(data)update({...data,status:'prepared'},'Ficha preparada en demo.')};$('publish-demo').onclick=()=>{if(current().status!=='approved'){note('Primero aprobá la ficha en demo.',true);return}update({status:'published'},'Publicada en el buscador de este navegador. No modifica la web pública.')};$('import-request').onchange=async e=>{try{const file=e.target.files[0];if(!file)return;if(file.size>40*1024*1024)throw Error();const raw=JSON.parse(await file.text());const rows=raw.businesses||[raw];if(!Array.isArray(rows)||!rows.every(b=>b&&typeof b.name==='string'&&typeof b.phone==='string'))throw Error();const next=[...db];for(const b of rows){const value={...b,id:b.id||crypto.randomUUID(),services:Array.isArray(b.services)?b.services.join('\n'):b.services||'',photos:Array.isArray(b.photos)?b.photos:[],status:'received'};const index=next.findIndex(x=>x.id===value.id);if(index>=0){note('Ese identificador ya existe. Importá una solicitud nueva para evitar sobrescribir cambios.',true);return}next.push(value)}if(persist(next)){selected=next[next.length-1].id;loadEditor();note('Solicitud importada. Quedó recibida y requiere revisión.')}}catch{note('No se pudo importar. Usá el archivo JSON descargado del formulario público.',true)}finally{e.target.value=''}};fetch('datos/fichas.json').then(r=>r.json()).then(data=>{if(!db.some(b=>b.id==='moravia-diaz')){const b=data.businesses.find(b=>b.id==='moravia-diaz');if(b){persist([...db,{...b,services:b.services.join('\n'),status:'prepared'}]);loadEditor()}}}).catch(()=>{});loadEditor();refreshFilters();renderSearch();})();
